// ResourceSamples is the newest counters this poller has seen, by sandbox ID.
// The map is a copy, so the caller can hold it across ticks.
func (p *sandboxAgentStatusPoller) ResourceSamples() map[string]sandboxResourceSample {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make(map[string]sandboxResourceSample, len(p.samples))
	for id, sample := range p.samples {
		out[id] = sample
	}
	return out
}

// tick polls every currently-running hosted sandbox but the configure ones,
// which tickConfigure polls, each independently, so one unreachable or
// erroring sandbox never blocks or fails the batch, then pushes whatever was
// successfully collected this tick.
func (p *sandboxAgentStatusPoller) tick(ctx context.Context) {
	sandboxes, err := p.runtime.ListSandboxes(ctx)
	if err != nil {
		p.logger.Warn("list sandboxes for status poll", "error", err)
		return
	}
	configure, err := p.runtime.RunningSandboxIDsInMode(ctx, sandboxconfig.HarnessModeConfig)
	if err != nil {
		// tickConfigure cannot find them either, so they are polled here.
		p.logger.Warn("list configure sandboxes for status poll", "error", err)
	}
	var running []string
	for _, sb := range sandboxes {
		if sb != nil && sb.Status == sandboxruntime.StatusRunning && strings.TrimSpace(sb.SandboxID) != "" && !slices.Contains(configure, sb.SandboxID) {
			running = append(running, sb.SandboxID)
		}
	}
	p.pollAndReport(ctx, running)
	// The standing tick's alone: nobody reads a configure sandbox that has
	// stopped, and its one-second poll is no cadence to hash screens at
	// (ADR 26-10-11-657 §2).
	p.reportInventories(ctx, running)
}

// tickConfigure polls only the running configure sandboxes, between the
// standing ticks. Finding them is one filtered list, so a pool with none pays
// next to nothing for it.
func (p *sandboxAgentStatusPoller) tickConfigure(ctx context.Context) {
	running, err := p.runtime.RunningSandboxIDsInMode(ctx, sandboxconfig.HarnessModeConfig)
	if err != nil {
		p.logger.Warn("list configure sandboxes for status poll", "error", err)
		return
	}
	p.pollAndReport(ctx, running)
}

// pollAndReport polls each of running and pushes what it collected as one
// batch.
func (p *sandboxAgentStatusPoller) pollAndReport(ctx context.Context, running []string) {
	if len(running) == 0 {
		return
	}
	tokens := p.ensureTokens(ctx, running)

	var mu sync.Mutex
	var wg sync.WaitGroup
	entries := make([]SandboxAgentStatusEntry, 0, len(running))
	for _, sandboxID := range running {
		token, ok := tokens[sandboxID]
		if !ok {
			continue
		}
		wg.Add(1)
		go func(sandboxID, token string) {
			defer wg.Done()
			entry, err := p.pollOne(ctx, sandboxID, token)
			if err != nil {
				p.logger.Warn("poll sandbox-agent status", "sandboxId", sandboxID, "error", err)
				return
			}
			mu.Lock()
			entries = append(entries, entry)
			mu.Unlock()
			if entry.Resources != nil {
				p.mu.Lock()
				p.samples[sandboxID] = sandboxResourceSample{Usage: *entry.Resources}
				p.mu.Unlock()
			}
		}(sandboxID, token)
	}
	wg.Wait()

	if len(entries) == 0 {
		return
	}
	if err := p.client.ReportSandboxAgentStatus(ctx, SandboxAgentStatusReportRequest{
		ControlPlaneURL: p.bootstrap.ControlPlaneURL,
		ProjectID:       p.bootstrap.ProjectID,
		PoolID:          p.bootstrap.PoolID,
		PrivateKey:      p.identity.PrivateKey,
		Sandboxes:       entries,
	}); err != nil {
		p.logger.Warn("push sandbox-agent status batch", "error", err)
	}
}

func (p *sandboxAgentStatusPoller) pollOne(ctx context.Context, sandboxID, token string) (SandboxAgentStatusEntry, error) {
	callCtx, cancel := context.WithTimeout(ctx, sandboxAgentStatusCallTimeout)
	defer cancel()
	dial, err := p.runtime.SandboxDialer(callCtx, sandboxID, sandboxruntime.SandboxAgentPort)
	if err != nil {
		return SandboxAgentStatusEntry{}, err
	}
	statusURL := sandboxruntime.HTTPURL(sandboxruntime.SandboxAgentPort, fmt.Sprintf("/api/projects/%s/sandboxes/%s/status", p.bootstrap.ProjectID, sandboxID))
	req, err := http.NewRequestWithContext(callCtx, http.MethodGet, statusURL.String(), nil)
	if err != nil {
		return SandboxAgentStatusEntry{}, err
	}
	// The connection is no credential: the sandbox agent decides on this
	// status:read token alone, whatever carried it (ADR 0126 §5).
	req.Header.Set("Authorization", "Bearer "+token)
	resp, err := (&http.Client{Transport: dial.Transport()}).Do(req)
	if err != nil {
		return SandboxAgentStatusEntry{}, err
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return SandboxAgentStatusEntry{}, err
