// open is the checkout at target, worked on as whoever owns it. A target that
// does not exist yet is created, owned by the sandbox user: in a container the
// boot wired it from the pool's sources volume, but a VM guest has no such
// volume and its sources arrive by this clone alone.
func (c *Converger) open(target string) (*repository, error) {
	info, err := os.Stat(target)
	if errors.Is(err, os.ErrNotExist) {
		if err = c.createTarget(target); err == nil {
			info, err = os.Stat(target)
		}
	}
	if err != nil {
		return nil, fmt.Errorf("source target: %w", err)
	}

// createTarget makes target and whichever of its parents are missing, each
// given to the sandbox user, so the checkout and any directory leading to it
// that only it needed are the user's, as a wired source's are.
func (c *Converger) createTarget(target string) error {
	target = filepath.Clean(target)
	var missing []string
	for dir := target; ; dir = filepath.Dir(dir) {
		if _, err := os.Stat(dir); err == nil {
			break
		} else if !errors.Is(err, os.ErrNotExist) {
			return err
		}
		missing = append(missing, dir)
		if parent := filepath.Dir(dir); parent == dir {
			break
		}
	}
	for i := len(missing) - 1; i >= 0; i-- {
		if err := os.Mkdir(missing[i], 0o755); err != nil && !errors.Is(err, os.ErrExist) {
			return err
		}
		if c.cfg.User != nil {
			if err := chownTo(missing[i], c.cfg.User); err != nil {
				return err
			}
		}
	}
	return nil
}

